fn divide_safely(a: Int, b: Int) -> Option[Int] {
  if b == 0 {
    return None;
  }
  return Some(a / b);
}

fn safe_max(a: Int, b: Int, c: Int) -> Option[Int] {
  let max_val = a;
  let max_val = if b > max_val { b } else { max_val };
  let max_val = if c > max_val { c } else { max_val };
  if max_val < 0 { return None; }
  return Some(max_val);
}

fn main() -> Int {
  let d1 = divide_safely(20, 4);
  let d2 = divide_safely(20, 0);
  io.println(d1.unwrap_or(0));
  io.println(d2.unwrap_or(0));

  let m1 = safe_max(1, 5, 3);
  let m2 = safe_max(-1, -2, -3);
  io.println(m1.unwrap_or(0));
  io.println(m2.unwrap_or(0));
  return 0;
}
